31	        {
32	            Id = s.Id,
33	            Position = new Vector3(s.X, s.Y, s.Z),
34	            Velocity = Vector3.Zero,
35	        };
36	        _entities.Add(e);
37	        _events.Add(
38	            new Dictionary<string, object?>
39	            {
40	                ["type"] = "spawn",
41	                ["tick"] = s.Tick,
42	                ["entity"] = s.Id,
