50	    private void ApplyImpulse(ImpulseEntry imp)
51	    {
52	        var e = _entities.FirstOrDefault(x => x.Id == imp.Entity);
53	        if (e == null)
54	            return;
55	        e.Velocity = Vector3.Add(e.Velocity, new Vector3(imp.Dx, imp.Dy, imp.Dz));
56	        _trace.UsedVector3Math = true;
57	        _events.Add(
58	            new Dictionary<string, object?>
59	            {
60	                ["type"] = "impulse",
61	                ["tick"] = imp.Tick,
62	                ["entity"] = imp.Entity,
63	                ["dx"] = imp.Dx,
64	                ["dy"] = imp.Dy,
65	                ["dz"] = imp.Dz,
66	            }
67	        );
68	    }
